import{_ as d,o as r,c as i,a4 as o}from"./chunks/framework.vNSRaLQv.js";const M=JSON.parse('{"title":"KVM/QEMU 虚拟机翻车全记录","description":"","frontmatter":{"title":"KVM/QEMU 虚拟机翻车全记录","date":"2026-07-20T00:00:00.000Z"},"headers":[],"relativePath":"posts/VM翻车记录.md","filePath":"posts/VM翻车记录.md"}'),e={name:"posts/VM翻车记录.md"};function a(l,t,n,s,h,c){return r(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="kvm-qemu-虚拟机翻车全记录" tabindex="-1">KVM/QEMU 虚拟机翻车全记录 <a class="header-anchor" href="#kvm-qemu-虚拟机翻车全记录" aria-label="Permalink to &quot;KVM/QEMU 虚拟机翻车全记录&quot;">​</a></h1><h2 id="硬件环境" tabindex="-1">硬件环境 <a class="header-anchor" href="#硬件环境" aria-label="Permalink to &quot;硬件环境&quot;">​</a></h2><ul><li>CPU: AMD Lucienne APU（笔记本核显）</li><li>GPU: AMD Radeon Graphics (1002:164c) — 唯一显卡</li><li>RAM: 单条 8GB</li><li>存储: Samsung PM981 NVMe 512GB（系统盘）</li><li>网卡: MediaTek MT7921 WiFi</li><li>读卡器: Realtek RTS522A</li></ul><h2 id="iommu-分组-灾难级" tabindex="-1">IOMMU 分组（灾难级） <a class="header-anchor" href="#iommu-分组-灾难级" aria-label="Permalink to &quot;IOMMU 分组（灾难级）&quot;">​</a></h2><p>AMD APU 的 IOMMU 分组极其不合理，几乎所有重要设备都捆在一起：</p><table tabindex="0"><thead><tr><th>Group</th><th>设备</th><th>备注</th></tr></thead><tbody><tr><td>0-1</td><td>PCIe Dummy Host Bridge</td><td>没用</td></tr><tr><td>2-4</td><td>PCIe GPP Bridge</td><td>桥接，不能单独直通</td></tr><tr><td><strong>5</strong></td><td><strong>GPU + USB×2 + SATA×2 + 音频×3 + 加密 + 桥接×3</strong></td><td><strong>12个设备全绑一起</strong></td></tr><tr><td>6</td><td>SMBus + LPC Bridge</td><td>宿主机必须保留</td></tr><tr><td>7</td><td>8个 Host Bridge</td><td>没用</td></tr><tr><td>8</td><td>NVMe SSD</td><td>系统盘，不能动</td></tr><tr><td>9</td><td>Realtek 读卡器</td><td>可以直通但没意义</td></tr><tr><td>10</td><td>MediaTek WiFi</td><td>可以直通但宿主机断网</td></tr></tbody></table><p><strong>结论：想直通 GPU = 必须同时交出 USB、SATA、音频 = 宿主机变砖</strong></p><h2 id="失败-1-usb-直通" tabindex="-1">失败 1：USB 直通 <a class="header-anchor" href="#失败-1-usb-直通" aria-label="Permalink to &quot;失败 1：USB 直通&quot;">​</a></h2><p><strong>尝试：</strong> 把 FT232 串口、USB 盘、USB 网卡直通给虚拟机</p><p><strong>结果：</strong> 全部 Windows 错误 10（无法启动设备）</p><p><strong>排查过程：</strong></p><ul><li><code>virsh attach-device</code> 报告成功，但 QEMU 实际没有接管设备</li><li>xhci_hcd 驱动在宿主机重新认领设备</li><li><code>managed=&#39;yes&#39;</code> 没有正确解绑宿主机驱动</li><li>尝试手动 <code>virsh nodedev-detach</code> + 重新绑定 vfio-pci → 无效</li><li>尝试改 USB 控制器型号（EHCI/OHCI/XHCI）→ 无效</li><li>根本原因不明，可能是 AMD USB 控制器 + libvirt 的兼容性问题</li></ul><h2 id="失败-2-gpu-直通" tabindex="-1">失败 2：GPU 直通 <a class="header-anchor" href="#失败-2-gpu-直通" aria-label="Permalink to &quot;失败 2：GPU 直通&quot;">​</a></h2><p><strong>尝试：</strong> 直通 IOMMU Group 5 全部 12 个设备</p><p><strong>准备：</strong></p><ol><li>GRUB 加 <code>amd_iommu=on iommu=pt</code> ✅</li><li><code>/etc/modprobe.d/vfio.conf</code> 绑定 Group 5 全部设备 ID ✅</li><li><code>/etc/initramfs-tools/modules</code> 加 vfio 模块 ✅</li><li>重建 initramfs + update-grub ✅</li><li>win11.xml 已有全部 hostdev 配置 ✅</li></ol><p><strong>结果：</strong> 重启后内核卡死，需要强制断电</p><p><strong>原因分析：</strong></p><ul><li>IOMMU 分组太烂，12 个设备捆在一起</li><li>直通过程中某个设备（可能是 USB 控制器或加密控制器）导致内核 panic</li><li>AMD APU 的 VFIO reset 存在已知 bug</li><li>宿主机只有一个 GPU，直通后本地显示也没了</li></ul><h2 id="失败-3-精简版-windows" tabindex="-1">失败 3：精简版 Windows <a class="header-anchor" href="#失败-3-精简版-windows" aria-label="Permalink to &quot;失败 3：精简版 Windows&quot;">​</a></h2><p><strong>使用的系统：</strong> &quot;不忘初心&quot; Windows 11 精简版</p><p><strong>问题：</strong></p><ul><li>无法安装 MSI 安装包 → virtio 驱动装不上、QXL 驱动装不上、OpenSSH 装不上</li><li>USB xHCI 驱动栈不完整 → 直通设备全部错误 10</li><li>缺少大量基础组件，基本是废的</li></ul><h2 id="最终结论" tabindex="-1">最终结论 <a class="header-anchor" href="#最终结论" aria-label="Permalink to &quot;最终结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>结论</th></tr></thead><tbody><tr><td>KVM GPU 直通</td><td>❌ AMD APU IOMMU 分组太烂，不可行</td></tr><tr><td>KVM USB 直通</td><td>❌ 不明原因失败，可能 AMD 兼容性问题</td></tr><tr><td>精简版 Windows</td><td>❌ 缺组件，什么都装不上</td></tr><tr><td>换 LTSC</td><td>⚠️ 能解决驱动问题，但 USB 直通可能还是不行</td></tr><tr><td>换 Proxmox/Unraid</td><td>❌ IOMMU 分组是硬件问题，换平台没用</td></tr><tr><td><strong>买亮机卡 GT710</strong></td><td>✅ <strong>唯一解</strong> — 分离 IOMMU，GPU 直通才能用</td></tr></tbody></table><h2 id="教训" tabindex="-1">教训 <a class="header-anchor" href="#教训" aria-label="Permalink to &quot;教训&quot;">​</a></h2><ol><li><strong>AMD APU 不适合玩虚拟化直通</strong> — IOMMU 分组是硬件层面的，软件解决不了</li><li><strong>精简版 Windows 基本不能用</strong> — 少了 MSI 安装能力，什么驱动都装不上</li><li><strong>USB 直通在 libvirt 上坑很多</strong> — VMware 的 USB 直通兼容性好得多</li><li><strong>强制断电伤硬盘</strong> — 这次折腾断了好几次电，以后要避免</li><li><strong>串口是最后的救命稻草</strong> — 没有屏幕没有键盘的时候，只有串口能救你</li></ol>',27)])])}const g=d(e,[["render",a]]);export{M as __pageData,g as default};
